<?php use App\Core\Money; ?>
<div class="topbar"><div><h1><?=e($doc['doc_no'])?></h1><p><?=e(ucwords(str_replace('_',' ',$type)))?> · <?=e($doc['status'])?></p></div><a class="btn btn-ghost" target="_blank" href="<?=url('/admin/'.$slug.'/'.$doc['id'].'/print')?>">Print</a></div><div class="card"><h3><?=e($doc['customer']['company_name']??'')?></h3><p><?=e($doc['customer']['email']??'')?></p><table><tr><th>Description</th><th>Qty</th><th>Total</th></tr><?php foreach($doc['items']??[] as $i):?><tr><td><?=e($i['description'])?></td><td><?=e($i['qty'])?></td><td><?=e(Money::format((int)$i['line_total_minor'],$doc['currency']))?></td></tr><?php endforeach;?></table><h2>Total <?=e(Money::format((int)$doc['total_minor'],$doc['currency']))?></h2><?php if($type==='quotation'&&$doc['status']==='draft'):?><form method="post" action="<?=url('/admin/'.$slug.'/'.$doc['id'].'/approve')?>"><?=csrf_field()?><button class="btn btn-primary">Approve quotation</button></form><?php endif;?><?php if($type!=='invoice'&&in_array($doc['status'],['approved','open','confirmed'])):?><form method="post" action="<?=url('/admin/'.$slug.'/'.$doc['id'].'/convert')?>"><?=csrf_field()?><button class="btn btn-primary">Convert to next document</button></form><?php endif;?></div><?php if($type==='invoice'):?><div class="card"><h3>Record payment</h3><form method="post" action="<?=url('/admin/'.$slug.'/'.$doc['id'].'/payments')?>"><?=csrf_field()?><input name="amount" placeholder="Amount" required><input type="date" name="paid_on" value="<?=date('Y-m-d')?>"><input name="method" placeholder="Method"><input name="reference" placeholder="Reference"><button class="btn btn-primary">Record payment</button></form><p>Paid: <?=e(Money::format((int)($doc['paid_minor']??0),$doc['currency']))?> · Balance: <?=e(Money::format((int)($doc['balance_minor']??$doc['total_minor']),$doc['currency']) )?></p></div><?php endif;?>
